import random

def get_overlaps(A, B):
    count = 0
    for i in A:
        for j in B:
            if max(i[0], j[0]) < min(i[1], j[1]):
                count += 1
    return count

def is_valid(S, k):
    endpoints = []
    for start, end in S:
        endpoints.append((start, 1))
        endpoints.append((end, -1))
    endpoints.sort()
    curr = 0
    max_curr = 0
    for _, type in endpoints:
        curr += type
        max_curr = max(max_curr, curr)
    return max_curr <= k

def solve_small(N, k):
    best = 0
    for _ in range(20000):
        A = []
        while len(A) < N:
            s = random.random()
            e = random.random()
            if s > e: s, e = e, s
            if is_valid(A + [(s, e)], k):
                A.append((s, e))

        B = []
        while len(B) < N:
            s = random.random()
            e = random.random()
            if s > e: s, e = e, s
            if is_valid(B + [(s, e)], k):
                B.append((s, e))

        best = max(best, get_overlaps(A, B))
    return best

print(f"N=3, k=2: {solve_small(3, 2)}")

